	var got TrailApprovalResponse
	if err := json.Unmarshal([]byte(body), &got); err != nil {
		t.Fatalf("decoding a real approve response failed: %v", err)
	}
	if !got.OK {
		t.Error("OK = false, want true")
	}
	if got.Approval.Author != "nodo" {
