package httpapi

import (
	"encoding/json"
	"time"

	"github.com/entirehq/entire-api/internal/store"
)

// Wire types for the trails surface. Field names and null semantics are the
// spike's contract (spikes/trails-service, RFD-023) — the BFF proxy, frontend,
// and CLI parse these exact shapes. No field is ever omitted; nullables
// serialize as explicit null; JSON-array columns always render as arrays.

type trailAuthor struct {
	ID    string  `json:"id"`
	Login *string `json:"login"`
}

type trailReviewer struct {
	Login  string `json:"login"`
	Status string `json:"status"`
}

type TrailListItem struct {
	ID                 string          `json:"id"`
	Number             int             `json:"number"`
	Title              string          `json:"title"`
	Status             string          `json:"status"`
	Branch             *string         `json:"branch"`
	OriginalBranch     *string         `json:"originalBranch"`
	Base               string          `json:"base"`
	Type               string          `json:"type"`
	Priority           string          `json:"priority"`
	Author             *trailAuthor    `json:"author"`
	Assignees          []string        `json:"assignees"`
	Reviewers          []trailReviewer `json:"reviewers"`
	RequestedReviewers []string        `json:"requestedReviewers"`
	HasCodeChanges     bool            `json:"hasCodeChanges"`
	CommentCount       int             `json:"commentCount"`
	UnresolvedCount    int             `json:"unresolvedCount"`
	CreatedAt          string          `json:"createdAt"`
	UpdatedAt          string          `json:"updatedAt"`
	MergedAt           *string         `json:"mergedAt"`
	Phase              *string         `json:"phase"`
}

// TrailsListResponse is the API-standard list envelope (ledger §3): `items` +
// an opaque `nextPageToken` (null when there is no further page). `repo` is
// dropped — the caller already has it from the path. totalCount (ENT-1185) is
// the filtered result set's total row count, identical across every page of
// the same request.
type TrailsListResponse struct {
	Items         []TrailListItem `json:"items"`
	NextPageToken *string         `json:"nextPageToken"`
	TotalCount    int             `json:"totalCount"`
}

// TrailDetailResponse is the single-trail detail envelope: every TrailListItem
// field plus the detail-only bodyDocument (trail body editor document),
// monitors (trend-enriched monitor results, same shape as GET .../monitors),
// and the merge/compare SHA triple. mergeBaseSha/baseSha/headSha are
// store-authoritative (unlike checkpoints/checkpointCount/hasWritePermission,
// which are deliberately absent here — the BFF composes those from the
// git/checkpoint plane and a GitHub install check) and drive the BFF's /files
// snapshot-refs path and mergeability, same as trailUpdateJSON's SHA triple.
type TrailDetailResponse struct {
	TrailListItem
	BodyDocument trailBodyDocumentJSON  `json:"bodyDocument"`
	Monitors     []trailMonitorItemJSON `json:"monitors"`
	MergeBaseSHA *string                `json:"mergeBaseSha"`
	BaseSHA      *string                `json:"baseSha"`
	HeadSHA      *string                `json:"headSha"`
	GhPrID       *int                   `json:"ghPrId,omitempty"`
}

// isoMillis renders JS Date.toISOString() format: UTC, millisecond precision, Z.
func isoMillis(t time.Time) string {
	return t.UTC().Format("2006-01-02T15:04:05.000Z")
}

// jsonStringArray tolerantly decodes a JSONB column that should hold a string
// array: non-array/corrupt values and non-string elements are dropped (spike
// parity — legacy data may hold garbage).
func jsonStringArray(raw []byte) []string {
	out := []string{}
	var vals []any
	if len(raw) == 0 || json.Unmarshal(raw, &vals) != nil {
		return out
	}
	for _, v := range vals {
		if s, ok := v.(string); ok {
			out = append(out, s)
		}
	}
	return out
}

// jsonReviewerArray tolerantly decodes the reviewers JSONB column: a
// non-array value renders as []. Per element, an element that doesn't decode
// as a trailReviewer object (e.g. a bare number) is dropped rather than
// collapsing the whole array; unknown fields on an otherwise-valid object
// drop silently (json.Unmarshal's default behavior).
func jsonReviewerArray(raw []byte) []trailReviewer {
	out := []trailReviewer{}
	if len(raw) == 0 {
		return out
	}
	var elems []json.RawMessage
	if json.Unmarshal(raw, &elems) != nil {
		return out
	}
	for _, elem := range elems {
		var r trailReviewer
		if json.Unmarshal(elem, &r) == nil {
			out = append(out, r)
		}
	}
	return out
}

// deriveTrailPhase is the spike's trail-phase.ts lifted to Go (RFD-023: phase
// derivation moves with the domain). Only open trails have a phase (nil
// otherwise): reviewing when explicitly in_review or a reviewer is assigned,
// building once the branch has code changes (or legacy in_progress), planning
// before that.
func deriveTrailPhase(status string, hasCodeChanges bool, reviewerCount, requestedReviewerCount int) *string {
	phase := func(p string) *string { return &p }
	if status == "in_review" {
		return phase("reviewing")
	}
	if status != "open" && status != "in_progress" {
		return nil
	}
	if reviewerCount > 0 || requestedReviewerCount > 0 {
		return phase("reviewing")
	}
	if status == "in_progress" || hasCodeChanges {
		return phase("building")
	}
	return phase("planning")
}

// toTrailListItem maps a store row to the wire shape. logins maps author
// account ULIDs to GitHub logins (resolution is best-effort: a missing entry
// yields author.login = null, never an error).
func toTrailListItem(row store.TrailListRow, logins map[string]string) TrailListItem {
	// branch and original_branch ride the wire raw (null for an empty column),
	// matching the legacy list shape: the BFF derives the history branch itself
	// via branch ?? original_branch, so a renamed/removed branch (branch null,
	// original_branch set) keeps its fallback there.
	branch := strPtr(row.Branch)
	originalBranch := strPtr(row.OriginalBranch)
	priority := row.Priority
	if priority == "" {
		priority = "none"
	}
	var author *trailAuthor
	if row.AuthorAccountID != "" {
		author = &trailAuthor{ID: row.AuthorAccountID}
		if login, ok := logins[row.AuthorAccountID]; ok && login != "" {
			author.Login = &login
		}
	}
	var mergedAt *string
	if row.MergedAt != nil {
		s := isoMillis(*row.MergedAt)
		mergedAt = &s
	}
	reviewers := jsonReviewerArray(row.Reviewers)
	requested := jsonStringArray(row.RequestedReviewers)
	return TrailListItem{
		ID: row.ID, Number: row.Number, Title: row.Title, Status: row.Status,
		Branch: branch, OriginalBranch: originalBranch, Base: row.Base, Type: row.Type, Priority: priority,
		Author: author, Assignees: jsonStringArray(row.Assignees),
		Reviewers: reviewers, RequestedReviewers: requested,
		HasCodeChanges: row.HasCodeChanges,
		CommentCount:   row.CommentCount, UnresolvedCount: row.UnresolvedCount,
		CreatedAt: isoMillis(row.CreatedAt), UpdatedAt: isoMillis(row.UpdatedAt),
		MergedAt: mergedAt,
		Phase:    deriveTrailPhase(row.Status, row.HasCodeChanges, len(reviewers), len(requested)),
	}
}

package httpapi

// Trails approvals route (RFD-023 trails-native port, PR 5 Task 10): submit a
// native approval decision and read the recorded history. Ported from main's
// GET/POST /:host/:owner/:repo/:number/approvals handlers
// (submitTrailApprovalHandler, trails.ts:5296-5427), reconciled to this cell:
//
//   - Write gate (push) on POST, pull gate on GET — same tiering as the other
//     trails routes (requireTrailsWriteAccess(ByID) / requireTrailsAccess(ByID)).
//   - Head sha resolution reads entiredb's ref mirror (repoContentClient.
//     ListRefs) instead of main's direct GitHub refs call or a forge seam —
//     entiredb mirrors every repo's git content regardless of host (ENT-1566;
//     matches reviews_read.go's diff/file reads). RepoAPIBase unconfigured,
//     or the branch simply not found, degrades to "" — never fails the
//     request (matches main's own branchRes.ok-false fallthrough, which also
//     just leaves commitSha "").
//   - Synchronous approvals-only re-eval (D2): main re-runs the full gates
//     ENGINE (`evaluateTrailGates({only:["approvals"]})`), which persists. This
//     cell has no engine — it re-runs only the pure, already-ported
//     gateeval.EvaluateApprovalsGate and ASSEMBLES a fresh evaluation
//     (approvals fresh in-memory + every other gate's latest stored row),
//     never inserting UNLESS deps.GateResultsWritable is set (the write-flip
//     seam, default false during the mirror phase). Both branches return an
//     identical response SHAPE; only whether the fresh approvals result was
//     actually persisted differs (an expected difference in the result's `id`
//     field, not a violation of "identical wire" — see the PR5 plan's design
//     decision 2).
//   - The re-eval is best-effort end to end: ANY failure (gates disabled, no
//     known head, missing approvals definition, a store error reading other
//     gates/definitions) degrades to `gates: null` in the response — the
//     approval itself is already durably recorded by UpdateReviews before the
//     re-eval ever runs, so a re-eval failure must never fail the whole
//     request.

import (
	"context"
	"crypto/rand"
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"sort"
	"strings"
	"time"

	"github.com/danielgtaylor/huma/v2"
	"github.com/oklog/ulid/v2"

	"github.com/entirehq/entire-api/internal/httpapi/gateeval"
	"github.com/entirehq/entire-api/internal/store"
)

// GateCheckPublisher is this route's narrow view of *gatecheckpublish.Publisher —
// one method, so httpapi need not import it. Credential rationale lives on
// RepoActivityDeps.GateCheckPublisher.
type GateCheckPublisher interface {
	PublishForTrail(ctx context.Context, repoID, trailID string) error
}

// gateCheckPublishTimeout bounds the detached publish (STS mint + GitHub write) so a
// slow GitHub can't leak it past the shutdown grace period. Mirrors reviews.go's
// findingsRecomputeTimeout.
const gateCheckPublishTimeout = 5 * time.Second

// publishGateCheckRun republishes trailID's gate check run so an approval shows on
// GitHub now rather than at the next push. Fire-and-forget in a detached goroutine,
// mirroring reviews.go's findingsSyncReeval: the approval is already durably recorded,
// so the response never waits on GitHub and a failure is logged, not surfaced.
func publishGateCheckRun(ctx context.Context, deps *RepoActivityDeps, repoID, trailID string) {
	if deps.GateCheckPublisher == nil {
		return
	}
	go func() {
		pctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), gateCheckPublishTimeout)
		defer cancel()
		if err := deps.GateCheckPublisher.PublishForTrail(pctx, repoID, trailID); err != nil {
			// pctx, not ctx: the request's ctx dies when the response is written;
			// WithoutCancel keeps its values so trace association survives.
			slog.WarnContext(pctx, "approvals gate check-run publish failed (best-effort)",
				slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", trailID))
		}
	}()
}

// --- reviews/reviewers JSONB storage shapes ---------------------------------

// storedTrailApproval is one repo_trails.reviews[] element's on-disk JSON
// shape. No store method touched this JSONB column before this task (see the
// PR5 context pack's residual item 4), so this shape is this port's own
// choice — snake_case commit_sha/created_at are kept for parity with main's
// stored TrailApproval literal, in case a future mirroring phase reads/writes
// this same column from the BFF side. This is deliberately distinct from
// TrailApprovalWire (this file's HTTP response shape, camelCase per ledger
// §13.5): storage and wire representations are allowed to diverge.
type storedTrailApproval struct {
	ID        string  `json:"id"`
	Author    string  `json:"author"`
	Event     string  `json:"event"`
	Body      *string `json:"body"`
	CommitSha string  `json:"commit_sha"`
	CreatedAt string  `json:"created_at"`
}

// storedTrailReviews is the reviews JSONB column's wrapper shape
// ({"reviews":[...]}) — distinct from the reviewers column, which is a plain
// array (see trailReviewer/jsonReviewerArray, trails_types.go).
type storedTrailReviews struct {
	Reviews []storedTrailApproval `json:"reviews"`
}

func toGateEvalApproval(a storedTrailApproval) gateeval.TrailApproval {
	return gateeval.TrailApproval{ID: a.ID, Author: a.Author, Event: a.Event, Body: a.Body, CommitSha: a.CommitSha, CreatedAt: a.CreatedAt}
}

func toStoredApproval(a gateeval.TrailApproval) storedTrailApproval {
	return storedTrailApproval{ID: a.ID, Author: a.Author, Event: a.Event, Body: a.Body, CommitSha: a.CommitSha, CreatedAt: a.CreatedAt}
}

// parseTrailReviews tolerantly decodes the reviews JSONB column into the
// evaluator's TrailApproval slice, defaulting to an empty (never nil) slice
// on an absent/malformed column — same tolerant-decode posture as
// jsonReviewerArray/jsonStringArray (trails_types.go).
func parseTrailReviews(raw []byte) []gateeval.TrailApproval {
	if len(raw) == 0 {
		return []gateeval.TrailApproval{}
	}
	var stored storedTrailReviews
	if err := json.Unmarshal(raw, &stored); err != nil {
		return []gateeval.TrailApproval{}
	}
	out := make([]gateeval.TrailApproval, 0, len(stored.Reviews))
	for _, a := range stored.Reviews {
		out = append(out, toGateEvalApproval(a))
	}
	return out
}

// marshalTrailReviews builds the reviews JSONB column's {"reviews":[...]}
// wrapper from the evaluator's TrailApproval slice.
func marshalTrailReviews(approvals []gateeval.TrailApproval) (json.RawMessage, error) {
	stored := storedTrailReviews{Reviews: make([]storedTrailApproval, 0, len(approvals))}
	for _, a := range approvals {
		stored.Reviews = append(stored.Reviews, toStoredApproval(a))
	}
	return json.Marshal(stored)
}

// marshalTrailReviewers builds the reviewers JSONB column (a plain array,
// unlike reviews) from the evaluator's TrailReviewer slice, reusing
// trailReviewer's wire tags (trails_types.go) for the {login,status} shape —
// the same shape jsonReviewerArray already reads on the list/detail routes.
func marshalTrailReviewers(reviewers []gateeval.TrailReviewer) (json.RawMessage, error) {
	out := make([]trailReviewer, 0, len(reviewers))
	for _, r := range reviewers {
		out = append(out, trailReviewer{Login: r.Login, Status: r.Status})
	}
	return json.Marshal(out)
}

// reviewerLoginsSorted flattens the per-login reviewer map into a slice,
// sorted by login for deterministic test assertions and a stable stored
// reviewers array (main's Map iteration order is insertion order, which this
// cell doesn't need to reproduce — the plan leaves this call within scope).
func reviewerLoginsSorted(byLogin map[string]gateeval.TrailReviewer) []gateeval.TrailReviewer {
	out := make([]gateeval.TrailReviewer, 0, len(byLogin))
	for _, r := range byLogin {
		out = append(out, r)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Login < out[j].Login })
	return out
}

