// --- GET .../approvals --------------------------------------------------------

// trailApprovalsGetCore is GET .../approvals's shared body (ID-001
// dual-addressing).
func trailApprovalsGetCore(ctx context.Context, deps *RepoActivityDeps, numberRaw string) (*TrailApprovalsOutput, error) {
	rep, err := trailsRepoFromContext(ctx)
	if err != nil {
		return nil, err
	}
	row, err := resolveTrailByNumberParam(ctx, deps, rep.repoID, numberRaw)
	if err != nil {
		return nil, err
	}
	approvals := parseTrailReviews(row.Reviews)
	items := make([]TrailApprovalWire, 0, len(approvals))
	for _, a := range approvals {
		items = append(items, toTrailApprovalWire(a))
	}
	out := &TrailApprovalsOutput{}
	out.Body = TrailApprovalsResponse{Approvals: items}
	return out, nil
}

// --- POST .../approvals -------------------------------------------------------

// validateApprovalSubmit ports submitTrailApprovalHandler's body validation
// (trails.ts:5296-5427) verbatim in message text and order.
func validateApprovalSubmit(body trailApprovalSubmitBody, status, branch string) error {
	if body.Event != "APPROVE" && body.Event != "REQUEST_CHANGES" {
		return huma.Error400BadRequest("event must be APPROVE or REQUEST_CHANGES")
	}
	if body.Event == "REQUEST_CHANGES" && (body.Body == nil || strings.TrimSpace(*body.Body) == "") {
		return huma.Error400BadRequest("A comment is required when requesting changes")
	}
	if status != "open" {
		return huma.Error400BadRequest("Trail is not open")
	}
	if branch == "" {
		return huma.Error400BadRequest("Trail has no linked branch")
	}
	return nil
}

// trailApprovalSyncReeval runs the synchronous approvals-only re-eval (D2):
// best-effort end to end — any failure degrades to a nil *TrailGatesResponse
// rather than failing the whole request, since the approval is already
// durably recorded by UpdateReviews before this ever runs. reviewers/
// approvals are the just-updated (post-append) reviewer map / approval
// history, matching what was just persisted.
func trailApprovalSyncReeval(ctx context.Context, deps *RepoActivityDeps, repoID string, row store.TrailDetailRow, commitSha string, reviewers []gateeval.TrailReviewer, approvals []gateeval.TrailApproval) *TrailGatesResponse {
	evalHead := commitSha
	if evalHead == "" {
		evalHead = row.HeadSHA
	}
	if evalHead == "" {
		return nil
	}

	gatesEnabled, err := deps.Store.GatesEnabledForRepo(ctx, repoID)
	if err != nil {
		slog.WarnContext(ctx, "approvals re-eval failed; returning gates:null",
			slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID))
		return nil
	}
	if !gatesEnabled {
		return nil
	}

	approvalsDef, ok, err := deps.Store.GateDefinitionByKey(ctx, repoID, "approvals", "approvals")
	if err != nil {
		slog.WarnContext(ctx, "approvals re-eval failed; returning gates:null",
			slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID))
		return nil
	}
	if !ok {
		return nil
	}
	def := toGateEvalDefinitionRow(approvalsDef)

	authorLogin := callerLogin(ctx, deps, row.AuthorAccountID)
	outcome := gateeval.EvaluateApprovalsGate(def, gateeval.ApprovalsEvalInputs{
		Reviewers: reviewers, Approvals: approvals, AuthorLogin: authorLogin, HeadSha: evalHead,
	})
	valueJSON, err := json.Marshal(outcome.Value)
	if err != nil {
		slog.WarnContext(ctx, "approvals re-eval failed; returning gates:null",
			slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID))
		return nil
	}
	rationale := outcome.Rationale
	now := time.Now().UTC()

	// The fresh approvals result, in-memory: ID "" because it was never
	// persisted (design decision 1) — this can never be confused with
	// HasMissingGateResults's "never evaluated" stand-in, which additionally
	// requires Status == "pending"; this result's Status is always
	// "passed"/"failed".
	freshRow := gateeval.GateResultRow{
		TrailID: row.ID, GateDefinitionID: approvalsDef.ID, GateKey: approvalsDef.GateKey,
		HeadSha: evalHead, Status: outcome.Status, BlockingSnapshot: approvalsDef.Blocking,
		Value: valueJSON, Rationale: &rationale, CreatedAt: now, UpdatedAt: now, CompletedAt: &now,
	}
	if deps.GateResultsWritable {
		inserted, err := deps.Store.InsertGateResult(ctx, store.GateResultInsertInput{
			TrailID: row.ID, GateDefinitionID: approvalsDef.ID, GateKey: approvalsDef.GateKey,
			HeadSha: evalHead, Status: outcome.Status, Blocking: approvalsDef.Blocking,
			Value: valueJSON, Rationale: &rationale,
		})
		if err == nil {
			freshRow = toGateEvalResultRow(inserted)
			// Only if the row we inserted is at the trail's current stored head:
			// PublishForTrail keys on row.HeadSHA, so on divergence (mirror lag, or a push
			// mid-review) we would publish this approval's rollup at a head it was never
			// evaluated against. Let a later push-triggered republish catch up instead.
			if evalHead == row.HeadSHA {
				publishGateCheckRun(ctx, deps, repoID, row.ID)
			}
		} else {
			// Swallowed (best-effort re-eval): fall back to freshRow for the response.
			// No publish — nothing persisted, so a republish would re-post the unchanged
			// pre-approval rollup.
			slog.ErrorContext(ctx, "approvals gate result insert failed",
				slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID),
				slog.String("gate_definition_id", approvalsDef.ID))
		}
	}

	otherRows, err := deps.Store.ListLatestGateResultsForHead(ctx, row.ID, evalHead)
	if err != nil {
		slog.WarnContext(ctx, "approvals re-eval failed; returning gates:null",
			slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID))
		return nil
	}
	latestByDefID := make(map[string]gateeval.GateResultRow, len(otherRows)+1)
	for _, r := range otherRows {
		latestByDefID[r.GateDefinitionID] = toGateEvalResultRow(r)
	}
	latestByDefID[approvalsDef.ID] = freshRow // overwrite any stale stored approvals row with the fresh one

	defRows, err := deps.Store.ListGateDefinitions(ctx, repoID)
	if err != nil {
		slog.WarnContext(ctx, "approvals re-eval failed; returning gates:null",
			slog.Any("error", err), slog.String("repo_id", repoID), slog.String("trail_id", row.ID))
		return nil
	}
	defs := gateEvalDefinitionRows(defRows)

	eval := gateeval.AssembleEvaluation(defs, latestByDefID, strPtr(row.HeadSHA), strPtr(evalHead))
	return &TrailGatesResponse{GateEvaluation: eval, GatesEnabled: true}
}

// resolveBranchHeadSHA resolves branch's current tip sha through entiredb's
// ref mirror (GET /repos/{id}/refs?prefix=refs/heads/<branch>) rather than a
// forge call — entiredb serves this git-content read for every host, gh
// included (ENT-1566). found=false with a nil error is a valid, expected
// outcome ("no such branch"), mirroring the GitHub forge's own BranchHeadSHA
// contract (a 404 branch-not-found there comes back OK with a nil value,
// never an error) — callers must not treat it as a failure.
func resolveBranchHeadSHA(ctx context.Context, deps *RepoActivityDeps, repoID, branch string) (sha string, found bool, err error) {
	if deps.RepoAPIBase == "" {
		return "", false, nil
	}
	ref := "refs/heads/" + branch
	refs, err := repoContentClient(ctx, deps).ListRefs(ctx, deps.RepoAPIBase, repoID, ref)
	if err != nil {
		return "", false, err
	}
	for _, r := range refs {
		if r.Name == ref {
			return r.OID, true, nil
		}
	}
	return "", false, nil
}

// trailApprovalSubmitCore is POST .../approvals's shared body (ID-001
// dual-addressing).
func trailApprovalSubmitCore(ctx context.Context, deps *RepoActivityDeps, numberRaw string, body trailApprovalSubmitBody) (*TrailApprovalSubmitOutput, error) {
	rep, err := trailsRepoFromContext(ctx)
	if err != nil {
		return nil, err
	}
	row, err := resolveTrailByNumberParam(ctx, deps, rep.repoID, numberRaw)
	if err != nil {
		return nil, err
	}
	if verr := validateApprovalSubmit(body, row.Status, row.Branch); verr != nil {
		return nil, verr
	}

	// Degrade, don't fail: an unresolvable head sha (RepoAPIBase unconfigured,
	// or the branch genuinely not found) just means commitSha stays "" —
	// matches main's own branchRes.ok-false path, which also never fails the
	// request over this.
	commitSha := ""
	if sha, found, herr := resolveBranchHeadSHA(ctx, deps, rep.repoID, row.Branch); herr != nil {
		slog.WarnContext(ctx, "repo-api branch-head-sha lookup failed; recording empty commit sha",
			slog.Any("error", herr), slog.String("repo_id", rep.repoID), slog.String("trail_id", row.ID))
	} else if found {
		commitSha = sha
		// Creation-time head seeding is best-effort, so repair a trail whose
		// branch head was unavailable when it was created. Use the effective
		// stored head if a concurrent push won this set-if-unset race; gate rows
		// must be evaluated against the trail head they will later be read under.
		if row.HeadSHA == "" {
			effectiveHead, _, setErr := deps.Store.SetTrailHeadSHAIfUnset(
				ctx, rep.repoID, row.ID, row.Branch, sha,
			)
			if setErr != nil {
				slog.WarnContext(ctx, "persist branch head sha during approval failed; continuing with resolved commit sha",
					slog.Any("error", setErr), slog.String("repo_id", rep.repoID), slog.String("trail_id", row.ID))
			} else if effectiveHead == "" {
				slog.WarnContext(ctx, "branch head sha during approval no longer eligible to persist",
					slog.String("repo_id", rep.repoID), slog.String("trail_id", row.ID), slog.String("branch", row.Branch))
			} else {
				commitSha = effectiveHead
				row.HeadSHA = effectiveHead
			}
		}
	}

	idULID, err := ulid.New(ulid.Timestamp(time.Now()), rand.Reader)
	if err != nil {
		return nil, huma.Error500InternalServerError("httpapi: generate approval id", err)
	}

	actorAccountID, err := callerAccountID(ctx)
	if err != nil {
		return nil, err
	}
	authorLogin := callerLogin(ctx, deps, actorAccountID)
	if authorLogin == "" {
		authorLogin = "unknown"
	}

	event := "changes_requested"
	if body.Event == "APPROVE" {
		event = "approved"
	}
	var approvalBody *string
	if body.Body != nil {
		if trimmed := strings.TrimSpace(*body.Body); trimmed != "" {
			approvalBody = &trimmed
		}
	}

	newApproval := gateeval.TrailApproval{
		ID: idULID.String(), Author: authorLogin, Event: event, Body: approvalBody,
		CommitSha: commitSha, CreatedAt: time.Now().UTC().Format(time.RFC3339Nano),
	}

	var updatedReviews []gateeval.TrailApproval
	var reviewers []gateeval.TrailReviewer
	ok, err := deps.Store.UpdateReviews(ctx, rep.repoID, row.ID, authorLogin,
		func(existingReviews, _ json.RawMessage) (store.ReviewsUpdate, error) {
			existing := parseTrailReviews(existingReviews)
			updatedReviews = make([]gateeval.TrailApproval, 0, len(existing)+1)
			updatedReviews = append(updatedReviews, existing...)
			updatedReviews = append(updatedReviews, newApproval)

			reviewerByLogin := make(map[string]gateeval.TrailReviewer, len(updatedReviews))
			for _, a := range updatedReviews {
				status := "changes_requested"
				if a.Event == "approved" {
					status = "approved"
				}
				reviewerByLogin[a.Author] = gateeval.TrailReviewer{Login: a.Author, Status: status}
			}
			reviewers = reviewerLoginsSorted(reviewerByLogin)

			reviewsJSON, err := marshalTrailReviews(updatedReviews)
			if err != nil {
				return store.ReviewsUpdate{}, fmt.Errorf("httpapi: marshal reviews: %w", err)
			}
			reviewersJSON, err := marshalTrailReviewers(reviewers)
			if err != nil {
				return store.ReviewsUpdate{}, fmt.Errorf("httpapi: marshal reviewers: %w", err)
			}
			return store.ReviewsUpdate{Reviews: reviewsJSON, Reviewers: reviewersJSON}, nil
		})
	if err != nil {
		return nil, huma.Error500InternalServerError("store: update reviews", err)
	}
	if !ok {
		// store.UpdateReviews's (false, nil) conflates "trail no longer open"
		// and "active merge reservation held" — but this handler already
		// validated status=="open" above in this same request, so a false
		// return at this point can only mean a race that just acquired a
		// reservation (or closed the trail) between that check and the
		// update's own transactional re-check. 409 is safe here (matches
		// main exactly).
		return nil, huma.Error409Conflict("Trail is currently merging")
	}

	gates := trailApprovalSyncReeval(ctx, deps, rep.repoID, row, commitSha, reviewers, updatedReviews)

	out := &TrailApprovalSubmitOutput{}
	out.Body = TrailApprovalSubmitResponse{OK: true, Approval: toTrailApprovalWire(newApproval), Gates: gates}
	return out, nil
}

