// registerTrailsApprovals registers the dual-addressed (ID-001) approvals
// routes: GET is pull-gated, POST is push-gated (write surface, same tiering
// as trails_write.go's create/update/delete). Called from registerTrails
// (trails.go).
func registerTrailsApprovals(api huma.API, deps *RepoActivityDeps) {
	readGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccess(api, deps)}
	readByIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsAccessByID(api, deps)}
	writeGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccess(api, deps)}
	writeByIDGate := []opMiddleware{requireAuth(api, &deps.baseDeps), requireTrailsWriteAccessByID(api, deps)}

	huma.Register(api, teamOp("trailsApprovals", http.MethodGet,
		"/trails/{host}/{owner}/{repo}/{number}/approvals", "List a trail's recorded approval decisions", "trail-approvals", readGate),
		func(ctx context.Context, in *TrailApprovalsInput) (*TrailApprovalsOutput, error) {
			return trailApprovalsGetCore(ctx, deps, in.Number)
		})
	huma.Register(api, teamOp("trailsApprovalsByRepoID", http.MethodGet,
		"/repos/{repo_id}/trails/{number}/approvals", "List a trail's recorded approval decisions (repo_id addressing)", "trail-approvals", readByIDGate),
		func(ctx context.Context, in *TrailApprovalsByRepoIDInput) (*TrailApprovalsOutput, error) {
			return trailApprovalsGetCore(ctx, deps, in.Number)
		})

	submitOp := teamOp("trailsApprovalsSubmit", http.MethodPost,
		"/trails/{host}/{owner}/{repo}/{number}/approvals", "Submit an approval decision on a trail", "trail-approvals", writeGate)
	submitOp.Errors = withExtraErrors(submitOp.Errors, http.StatusNotFound, http.StatusConflict)
	huma.Register(api, submitOp,
		func(ctx context.Context, in *TrailApprovalSubmitInput) (*TrailApprovalSubmitOutput, error) {
			return trailApprovalSubmitCore(ctx, deps, in.Number, in.Body)
		})

	submitByIDOp := teamOp("trailsApprovalsSubmitByRepoID", http.MethodPost,
		"/repos/{repo_id}/trails/{number}/approvals", "Submit an approval decision on a trail (repo_id addressing)", "trail-approvals", writeByIDGate)
	submitByIDOp.Errors = withExtraErrors(submitByIDOp.Errors, http.StatusNotFound, http.StatusConflict)
	huma.Register(api, submitByIDOp,
		func(ctx context.Context, in *TrailApprovalSubmitByRepoIDInput) (*TrailApprovalSubmitOutput, error) {
			return trailApprovalSubmitCore(ctx, deps, in.Number, in.Body)
		})
}

